function readHeadAt(ledger: LedgerGitLayout, commit: string): EventHead | null { const body = showText(ledger.rootDir, commit, ledgerGitPath(ledger, "events/head.json")); if (body === null) return null; let head: EventHead; try { head = JSON.parse(body) as EventHead; } catch { throw new TaskEventStoreError("invalid_store", "event head is not JSON"); } if (serializeEventHead(head) !== body) throw new TaskEventStoreError("invalid_store", "event head is not canonical"); return head; }
